jQuery(function ($) {
  function hasUsablePrice(value) {
    return value !== "" && value !== null && value !== undefined && parseFloat(value) > 0;
  }

  function setTotalPriceVisible(isVisible) {
    const $wrap = $("#product_total_price");
    if (!$wrap.length) return;
    $wrap.prop("hidden", !isVisible).toggleClass("is-hidden-price", !isVisible);
  }

  function updateTotal() {
    const $price = $(".product-total-price_sum.price");
    if (!$price.length) return;

    const unit = parseFloat($price.attr("data-price")) || 0;
    if (unit <= 0) {
      setTotalPriceVisible(false);
      return;
    }

    const qty = parseFloat($(".quantity .qty").val()) || 1;
    const total = unit * qty;

    $price.text(themeWooSingle.currencySymbol + total.toFixed(2));
    setTotalPriceVisible(true);
  }

  $(document).on("click", "form.cart button.plus, form.cart button.minus", function () {
    const $qty = $(this).closest("form").find(".qty").first();
    if (!$qty.length) return;

    const val = parseFloat($qty.val()) || 0;
    const max = parseFloat($qty.attr("max"));
    const min = parseFloat($qty.attr("min")) || 1;
    const step = parseFloat($qty.attr("step")) || 1;

    if ($(this).hasClass("plus")) {
      $qty.val(max && val >= max ? max : val + step);
    } else {
      $qty.val(val <= min ? min : val - step);
    }

    $qty.trigger("change");
    setTimeout(updateTotal, 50);
  });

  $(document).on("change input", ".quantity .qty", updateTotal);

  $(document).on("show_variation", "form.cart", function (event, variation) {
    if (!variation) return;

    const rawPrice = variation.display_price;
    const price = hasUsablePrice(rawPrice) ? parseFloat(rawPrice) : 0;
    $(".product-total-price_sum.price").attr("data-price", price);

    if (variation.sku) {
      $(".sku-value").text(variation.sku);
    }

    updateTotal();
  });

  $(document).on("hide_variation", "form.cart", function () {
    setTotalPriceVisible(false);
  });

  updateTotal();
});
